-- Official Gangnam bulky-waste catalog verified against the public portal.
-- The 2025 public-data CSV and ordinance XLSX agree on their 146 common rows;
-- this catalog uses the newer 213-row portal export, including free-collection items.

create table public.waste_fee_catalog_sources (
  catalog_version text primary key,
  jurisdiction_name text not null,
  source_url text not null,
  source_checked_at date not null,
  verified_at date not null,
  ordinance_name text not null,
  ordinance_clause text not null,
  ordinance_url text not null,
  ordinance_effective_date date not null,
  ordinance_number text not null,
  row_count integer not null check (row_count > 0),
  source_dataset_sha256 text not null check (source_dataset_sha256 ~ '^[0-9A-F]{64}$'),
  evidence jsonb not null default '{}'::jsonb
);

alter table public.waste_fee_catalog_sources enable row level security;

insert into public.waste_fee_catalog_sources (
  catalog_version,
  jurisdiction_name,
  source_url,
  source_checked_at,
  verified_at,
  ordinance_name,
  ordinance_clause,
  ordinance_url,
  ordinance_effective_date,
  ordinance_number,
  row_count,
  source_dataset_sha256,
  evidence
) values (
  'gangnam-official-2026-08-04',
  '서울특별시 강남구',
  'https://clean.gangnam.go.kr/use/biwa/USEBIWA01000000.do',
  date '2026-08-04',
  date '2026-08-06',
  '서울특별시 강남구 폐기물 관리 조례',
  '제8조제1항제1호 및 별표 1',
  'https://www.law.go.kr/LSW/ordinInfoP.do?ordinSeq=2147835',
  date '2026-07-10',
  '강남구조례 제2120호',
  213,
  '55817E4D3545490C7057192114183C610396037C045A7A4D90F0F8488215C152',
  jsonb_build_object(
    'archive_sha256', '05A37A0A5FA26DFC4AA98D68EDCCBE0232D4EC45C4EE374AADC93947C22F7C00',
    'ordinance_xlsx_sha256', '30E5A475A008C9A4240FEE67B5E390DF37FD7468F42BF9B09A0634614AA4E414',
    'public_data_csv_sha256', 'DC045CB6BF32DD7B1A6E95A1E7D92EC81E24DB0ECAE225876A1BEE43A963E0D3',
    'public_data_as_of', '2025-07-07',
    'public_data_rows', 146
  )
)
on conflict (catalog_version) do update set
  jurisdiction_name = excluded.jurisdiction_name,
  source_url = excluded.source_url,
  source_checked_at = excluded.source_checked_at,
  verified_at = excluded.verified_at,
  ordinance_name = excluded.ordinance_name,
  ordinance_clause = excluded.ordinance_clause,
  ordinance_url = excluded.ordinance_url,
  ordinance_effective_date = excluded.ordinance_effective_date,
  ordinance_number = excluded.ordinance_number,
  row_count = excluded.row_count,
  source_dataset_sha256 = excluded.source_dataset_sha256,
  evidence = excluded.evidence;

alter table public.waste_fee_catalog
  add column catalog_version text references public.waste_fee_catalog_sources(catalog_version),
  add column official_category text,
  add column specification text,
  add column catalog_order integer,
  add column match_kind text;

delete from public.waste_fee_catalog;

