alter table public.waste_fee_catalog
  alter column fee set not null,
  alter column size_label set not null,
  alter column catalog_version set not null,
  alter column official_category set not null,
  alter column specification set not null,
  alter column catalog_order set not null,
  alter column match_kind set not null,
  add constraint waste_fee_catalog_match_kind_check
    check (match_kind in ('all', 'label', 'longest_side_cm', 'confirmation')),
  add constraint waste_fee_catalog_official_row_unique
    unique (catalog_version, official_category, item_name, specification),
  add constraint waste_fee_catalog_order_unique
    unique (catalog_version, catalog_order);

create index waste_fee_catalog_item_name_idx
  on public.waste_fee_catalog (item_name);

create table public.waste_disposal_policies (
  policy_key text primary key,
  jurisdiction_name text not null,
  title text not null,
  policy_text text not null,
  action_code text not null check (
    action_code in ('use_similar_item', 'use_other_item', 'confirm_official_application')
  ),
  source_url text not null,
  source_checked_at date not null,
  catalog_version text not null references public.waste_fee_catalog_sources(catalog_version),
  active boolean not null default true
);

alter table public.waste_disposal_policies enable row level security;

