do $$
begin
  if (select count(*) from public.waste_fee_catalog
      where catalog_version = 'gangnam-official-2026-08-04') <> 213 then
    raise exception 'Gangnam fee catalog must contain 213 official rows';
  end if;
  if (select count(*) from public.waste_fee_catalog
      where catalog_version = 'gangnam-official-2026-08-04' and fee = 0) <> 34 then
    raise exception 'Gangnam fee catalog must contain 34 zero-fee rows';
  end if;
  if (select count(distinct item_name) from public.waste_fee_catalog
      where catalog_version = 'gangnam-official-2026-08-04') <> 126 then
    raise exception 'Gangnam fee catalog must contain 126 distinct official item names';
  end if;
end
$$;
